## JavaScript Side

```typescript
// src/lib/directory.ts
import { invoke } from '@tauri-apps/api/core';

export interface DirectoryEntry {
  name: string;
  path: string;
  is_dir: boolean;
  size: number | null;
}

export async function listDirectoryContents(dirPath: string): Promise<DirectoryEntry[]> {
  try {
    // Validate input before sending to backend
    if (!dirPath || typeof dirPath !== 'string') {
      throw new Error('Invalid directory path');
    }

    // Call the Tauri command
    const entries = await invoke<DirectoryEntry[]>('list_directory_contents', {
      dirPath
    });

    return entries;
  } catch (error) {
    console.error('Failed to list directory contents:', error);
    throw error;
  }
}
```

```typescript
// src/App.tsx
import React, { useState, useEffect } from 'react';
import { listDirectoryContents, DirectoryEntry } from './lib/directory';

function App() {
  const [currentPath, setCurrentPath] = useState<string>('');
  const [entries, setEntries] = useState<DirectoryEntry[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const loadDirectory = async (path: string) => {
    setLoading(true);
    setError(null);
    try {
      const result = await listDirectoryContents(path);
      setEntries(result);
      setCurrentPath(path);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load directory');
      setEntries([]);
    } finally {
      setLoading(false);
    }
  };

  const handleEntryClick = (entry: DirectoryEntry) => {
    if (entry.is_dir) {
      loadDirectory(entry.path);
    }
  };

  return (
    <div className="app">
      <h1>Directory Browser</h1>

      <div className="path-bar">
        <input
          type="text"
          value={currentPath}
          onChange={(e) => setCurrentPath(e.target.value)}
          placeholder="Enter directory path"
        />
        <button onClick={() => loadDirectory(currentPath)} disabled={loading}>
          Browse
        </button>
      </div>

      {error && <div className="error">{error}</div>}

      {loading ? (
        <div>Loading...</div>
      ) : (
        <ul className="directory-list">
          {entries.map((entry, index) => (
            <li
              key={index}
              onClick={() => handleEntryClick(entry)}
              className={entry.is_dir ? 'directory' : 'file'}
            >
              <span className="icon">{entry.is_dir ? '📁' : '📄'}</span>
              <span className="name">{entry.name}</span>
              {!entry.is_dir && entry.size !== null && (
                <span className="size">
                  {formatFileSize(entry.size)}
                </span>
              )}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

function formatFileSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  if (bytes < 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  return `${(bytes / (1024 * 1024 * 1024)).toFixed(1)} GB`;
}

export default App;
```

## Security Notes

**Security decisions implemented:**
1. **Path confinement**: The backend canonicalizes paths and restricts access to the app's data directory only, preventing directory traversal attacks
2. **No generic invoke**: The Tauri command is a named, typed function with explicit parameters
3. **Input validation**: Both frontend and backend validate the directory path input
4. **CSP configured**: Content Security Policy restricts connections to IPC only
5. **No shell execution**: Uses Rust's `fs` module directly instead of shell commands
